const incoming = items[0]?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const brand = body.brand || incoming.brand || {};
const officialWebsite = String(body.officialWebsite || incoming.officialWebsite || brand.officialWebsite || brand.website || '').trim();
const requestedUrls = Array.isArray(body.researchUrls) ? body.researchUrls : Array.isArray(incoming.researchUrls) ? incoming.researchUrls : [];
const requestedSitemaps = Array.isArray(body.sitemapUrls) ? body.sitemapUrls : Array.isArray(incoming.sitemapUrls) ? incoming.sitemapUrls : [];

function normalizeUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw.startsWith('http') ? raw : 'https://' + raw);
    url.hash = '';
    return url.toString();
  } catch (error) {
    return '';
  }
}

function sameOriginPath(baseUrl, pathname) {
  try {
    const url = new URL(baseUrl);
    url.pathname = pathname;
    url.search = '';
    url.hash = '';
    return url.toString();
  } catch (error) {
    return '';
  }
}

function inferLanguage({ brand, officialWebsite }) {
  const explicit = String(brand.language || brand.defaultLanguage || brand.locale || body.language || '').toLowerCase();
  if (explicit.startsWith('en')) return 'en';
  if (explicit.startsWith('es')) return 'es';

  const haystack = [brand.slug, brand.name, brand.shortName, brand.description, brand.officialWebsite, officialWebsite]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  if (/\.edu\.co|universidad|fundacion|fundaci?n|politecnico|polit?cnico|corporacion|corporaci?n|uniminuto|ean|minuto|bogota|bogot?|colombia/.test(haystack)) return 'es';
  if (/\.edu|college|school|institute|health|training|center|academy|university|campus|career/.test(haystack)) return 'en';
  return 'es';
}

const preferredLanguage = inferLanguage({ brand, officialWebsite });
const urls = new Map();

function addUrl(value, sourceType = 'page', priority = 10) {
  const url = normalizeUrl(value);
  if (!url) return;
  const current = urls.get(url);
  if (!current || priority < current.priority) urls.set(url, { url, sourceType, priority });
}

[officialWebsite, ...requestedUrls].forEach((url) => addUrl(url, 'manual-or-official', 1));

if (officialWebsite) {
  const normalizedOfficial = normalizeUrl(officialWebsite);
  const hostname = normalizedOfficial ? new URL(normalizedOfficial).hostname : '';
  const sitemapPaths = ['/sitemap.xml', '/sitemap_index.xml', '/page-sitemap.xml', '/wp-sitemap-posts-page-1.xml', '/sitemap-pages.xml'];

  [...requestedSitemaps, ...sitemapPaths.map((itemPath) => sameOriginPath(normalizedOfficial, itemPath))]
    .filter(Boolean)
    .forEach((url) => addUrl(url, 'sitemap', 2));

  const bilingualInstitutionalPaths = [
    '/', '/about', '/about-us', '/about-us/mission-vision', '/mission', '/mission-and-vision', '/mission-vision', '/vision-mission', '/history', '/leadership', '/accreditation', '/academics', '/programs', '/student-services', '/career-services', '/consumer-information', '/financial-aid', '/community', '/diversity', '/sustainability', '/research', '/innovation',
    '/la-universidad', '/la-universidad/quienes-somos', '/quienes-somos', '/mision', '/mision-y-vision', '/historia', '/sostenibilidad', '/investigacion', '/innovacion', '/proyeccion-social', '/bienestar-universitario'
  ];

  bilingualInstitutionalPaths
    .map((itemPath) => sameOriginPath(normalizedOfficial, itemPath))
    .filter(Boolean)
    .forEach((url) => addUrl(url, 'institutional-page', preferredLanguage === 'en' ? 5 : 6));

  if (hostname.includes('universidadean.edu.co')) {
    ['/la-universidad', '/la-universidad/quienes-somos', '/la-universidad/emprendimiento-sostenible', '/la-universidad/sedes/edificio-ean-legacy', '/noticias/el-instituto-para-el-emprendimiento-sostenible-se-transforma-en-impacta', '/la-universidad/quienes-somos/organigrama/procesos-misionales/proyeccion-social']
      .map((itemPath) => sameOriginPath(normalizedOfficial, itemPath))
      .filter(Boolean)
      .forEach((url) => addUrl(url, 'ean-known-source', 3));
  }
}

const sortedTargets = Array.from(urls.values())
  .sort((a, b) => a.priority - b.priority || a.url.localeCompare(b.url))
  .slice(0, 18);

const output = sortedTargets.map((target, index) => ({
  json: {
    url: target.url,
    sourceIndex: index + 1,
    sourceType: target.sourceType,
    preferredLanguage,
    brand,
    requestedDocumentText: String(body.documentText || body.text || '').slice(0, 18000)
  }
}));

if (output.length === 0) {
  return [{ json: { url: '', sourceIndex: 1, sourceType: 'fallback-no-url', preferredLanguage, brand, requestedDocumentText: String(body.documentText || incoming.documentText || body.text || incoming.text || '').slice(0, 18000), skipFetch: true } }];
}

return output;

const webhookInput = $('Webhook - University Profile Agent').first().json || {};
const webhookBody = webhookInput.body && typeof webhookInput.body === 'object' ? webhookInput.body : webhookInput;
const initialTargets = $('Prepare Research Targets').all();
const initialFetched = $('Fetch Official Pages').all();
const discoveredTargets = $('Select Valuable Sitemap Pages').all();
const discoveredFetched = items;
const brand = webhookBody.brand || webhookInput.brand || initialTargets[0]?.json?.brand || discoveredTargets[0]?.json?.brand || {};
const manualText = String(webhookBody.documentText || webhookInput.documentText || webhookBody.text || webhookInput.text || initialTargets[0]?.json?.requestedDocumentText || '').trim();
const preferredLanguage = String(webhookBody.language || initialTargets[0]?.json?.preferredLanguage || discoveredTargets[0]?.json?.preferredLanguage || 'es').startsWith('en') ? 'en' : 'es';

function stripTags(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function arrayText(value) {
  if (Array.isArray(value)) return value.map((item) => String(item || '').trim()).filter(Boolean);
  const text = String(value || '').trim();
  return text ? [text] : [];
}

function extractSitemapUrls(raw) {
  const text = String(raw || '');
  const matches = Array.from(text.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/gi)).map((match) => match[1].trim());
  return matches.filter(Boolean).filter((url) => /about|mission|vision|history|accredit|student|career|consumer|community|sustain|research|innovation|quienes|mision|historia|sostenibilidad|investigacion|proyeccion|bienestar|universidad|institution|leadership|diversity/i.test(url)).slice(0, 30).map((url) => 'Sitemap candidate: ' + url).join('\n');
}

function compactText(parts) {
  return parts.flatMap(arrayText).join('\n').replace(/\s+/g, ' ').replace(/\s+([.,;:])/g, '$1').trim().slice(0, 9000);
}

function getRaw(item) {
  const json = item?.json || {};
  return String(json.data || json.body || json.html || json.text || json.response || '').trim();
}

function buildSource(item, target, fallbackIndex, sourceTypeOverride) {
  const json = item?.json || {};
  const targetJson = target?.json || target || {};
  const raw = getRaw(item);
  const sourceType = sourceTypeOverride || targetJson.sourceType || 'page';
  const isSitemap = sourceType === 'sitemap' || /sitemap/i.test(targetJson.url || '');
  const sitemapHints = isSitemap ? extractSitemapUrls(raw) : '';
  const rawText = raw ? stripTags(raw).slice(0, isSitemap ? 7000 : 11000) : '';
  const extractedText = compactText([json.title, json.metaDescription, json.h1, json.h2, json.h3, json.p, json.li]);
  const content = [extractedText, sitemapHints, rawText].filter(Boolean).join('\n').slice(0, isSitemap ? 7000 : 12000);
  return { url: targetJson.url || json.url || '', sourceIndex: targetJson.sourceIndex || fallbackIndex, sourceType, score: targetJson.score || 0, discoveredFrom: targetJson.discoveredFrom || '', content };
}

const initialSources = initialFetched.map((item, index) => buildSource(item, initialTargets[index], index + 1));
const discoveredSources = discoveredFetched.map((item, index) => buildSource(item, discoveredTargets[index], index + 1, 'sitemap-discovered-page'));
const sources = [...discoveredSources, ...initialSources]
  .filter((source) => source.content || source.url)
  .sort((a, b) => {
    const typeWeight = (source) => source.sourceType === 'manual-document' ? -1 : source.sourceType === 'sitemap-discovered-page' ? 0 : 1;
    return typeWeight(a) - typeWeight(b) || (b.score || 0) - (a.score || 0);
  })
  .slice(0, 14);

if (manualText) sources.unshift({ url: 'manual-document-or-pasted-context', sourceIndex: 0, sourceType: 'manual-document', score: 100, discoveredFrom: '', content: manualText.slice(0, 12000) });

const researchContext = sources.map((source) => '[Source ' + source.sourceIndex + '] Type: ' + source.sourceType + (source.score ? ' Score: ' + source.score : '') + (source.discoveredFrom ? '\nDiscovered from: ' + source.discoveredFrom : '') + '\nURL: ' + source.url + '\n' + source.content).join('\n\n---\n\n').slice(0, 68000);

const expectedShape = {
  institutionalEssence: { whatItIs: '', whatItDoes: '', whoItServes: '' },
  mission: { statement: '', keyFocusAreas: [] },
  vision: { statement: '', targetYear: '', aspirations: [] },
  coreValues: [{ title: '', description: '' }],
  guidingPrinciples: [{ title: '', description: '' }],
  institutionalPhilosophy: { educationalModel: '', learningApproach: '', studentCenteredFocus: '' },
  history: { overview: '', milestones: [{ year: '', event: '' }] },
  strategicObjectives: [{ title: '', description: '' }],
  studentExperience: { campusLife: '', studentSupportServices: [], clubsAndOrganizations: [], leadershipOpportunities: [], internationalPrograms: [] },
  researchAndInnovation: { researchAreas: [], innovationInitiatives: [], industryPartnerships: [] },
  communityEngagement: { socialImpactPrograms: [], communityPartnerships: [], sustainabilityInitiatives: [] },
  graduateProfile: { description: '', competencies: [], professionalSkills: [], ethicalCommitments: [] },
  facultyProfile: { overview: '', qualifications: [], teachingStrengths: [] },
  competitiveAdvantages: [{ title: '', description: '' }],
  brandIdentity: { brandPromise: '', brandPersonality: [], uniqueValueProposition: '' },
  institutionalCulture: { cultureDescription: '', diversityAndInclusion: '', innovationMindset: '', collaborationApproach: '' },
  recognitionsAndAchievements: [{ year: '', recognition: '', organization: '' }],
  futureOutlook: { growthPlans: [], strategicPriorities: [], longTermGoals: [] }
};

const languageName = preferredLanguage === 'en' ? 'English' : 'Spanish';
const languageInstruction = preferredLanguage === 'en'
  ? 'Write every human-readable value in natural English. Do not translate section titles into Spanish. Use English titles such as Mission, Vision, Core Values, Student Support, Career Services, Accreditation when relevant.'
  : 'Write every human-readable value in natural Spanish. Use Spanish titles naturally when relevant.';

const systemPrompt = [
  'You are EDwin AI University Profile Agent.',
  'You are an expert higher-education researcher, institutional strategist, and enrollment marketing analyst.',
  'Use only the supplied official website content, sitemap-discovered page content, provided documents, and brand JSON.',
  'Prioritize sitemap-discovered pages with high scores because those were selected as likely institutional pages.',
  'Do not invent precise facts. If a field cannot be supported, leave it empty or infer cautiously using neutral language.',
  'Avoid duplicating basic brand fields such as logo, colors, website, official institution name, or landing/program data.',
  'Return strict JSON only. No markdown. No surrounding array.',
  'Output language: ' + languageName + '. ' + languageInstruction,
  'Use concise but useful strings. Arrays should contain 3 to 8 high-signal items when evidence supports them.',
  'The output must match the exact schema provided by the user prompt.'
].join(' ');

const userPrompt = ['Build a University Content Base profile for EDwin AI.', 'Output language: ' + languageName + '.', '', 'Brand JSON:', JSON.stringify(brand, null, 2), '', 'Research sources:', researchContext || 'No research sources were available. Return a mostly empty schema with any safe information from the brand JSON only.', '', 'Return only valid JSON matching this exact shape:', JSON.stringify(expectedShape, null, 2)].join('\n');

return [{ json: { ok: true, agent: 'edwin-university-profile-agent', brand, preferredLanguage, sourceCount: sources.length, sources: sources.map((source) => ({ url: source.url, sourceIndex: source.sourceIndex, sourceType: source.sourceType, score: source.score, discoveredFrom: source.discoveredFrom, hasContent: Boolean(source.content) })), systemPrompt, userPrompt } }];

const raw = $json.output ?? $json.text ?? $json.response ?? $json.message ?? $json;
const promptContext = $('Build University Profile Prompt').first().json;

function parseJsonCandidate(value) {
  if (typeof value === 'object' && value !== null) return value;
  if (typeof value !== 'string') return null;
  const cleaned = value
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

function text(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function list(value) {
  if (Array.isArray(value)) return value.map(text).filter(Boolean);
  const current = text(value);
  return current ? [current] : [];
}

function descriptionItems(value) {
  if (!Array.isArray(value)) return [];
  return value.map((item) => {
    if (!item || typeof item !== 'object') return null;
    return {
      title: text(item.title || item.name || item.objective),
      description: text(item.description)
    };
  }).filter((item) => item && (item.title || item.description));
}

const parsed = parseJsonCandidate(raw);

if (!parsed || !parsed.institutionalEssence) {
  return {
    json: {
      ok: false,
      agent: 'edwin-university-profile-agent',
      message: 'No se pudo generar un university profile valido',
      sourceCount: promptContext.sourceCount || 0,
      sources: promptContext.sources || [],
      rawOutput: raw
    }
  };
}

const profile = {
  institutionalEssence: {
    whatItIs: text(parsed.institutionalEssence?.whatItIs),
    whatItDoes: text(parsed.institutionalEssence?.whatItDoes),
    whoItServes: text(parsed.institutionalEssence?.whoItServes)
  },
  mission: {
    statement: text(parsed.mission?.statement),
    keyFocusAreas: list(parsed.mission?.keyFocusAreas)
  },
  vision: {
    statement: text(parsed.vision?.statement),
    targetYear: text(parsed.vision?.targetYear),
    aspirations: list(parsed.vision?.aspirations)
  },
  coreValues: descriptionItems(parsed.coreValues),
  guidingPrinciples: descriptionItems(parsed.guidingPrinciples),
  institutionalPhilosophy: {
    educationalModel: text(parsed.institutionalPhilosophy?.educationalModel),
    learningApproach: text(parsed.institutionalPhilosophy?.learningApproach),
    studentCenteredFocus: text(parsed.institutionalPhilosophy?.studentCenteredFocus)
  },
  history: {
    overview: text(parsed.history?.overview),
    milestones: Array.isArray(parsed.history?.milestones) ? parsed.history.milestones.map((item) => ({ year: text(item.year), event: text(item.event) })).filter((item) => item.year || item.event) : []
  },
  strategicObjectives: descriptionItems(parsed.strategicObjectives),
  studentExperience: {
    campusLife: text(parsed.studentExperience?.campusLife),
    studentSupportServices: list(parsed.studentExperience?.studentSupportServices),
    clubsAndOrganizations: list(parsed.studentExperience?.clubsAndOrganizations),
    leadershipOpportunities: list(parsed.studentExperience?.leadershipOpportunities),
    internationalPrograms: list(parsed.studentExperience?.internationalPrograms)
  },
  researchAndInnovation: {
    researchAreas: list(parsed.researchAndInnovation?.researchAreas),
    innovationInitiatives: list(parsed.researchAndInnovation?.innovationInitiatives),
    industryPartnerships: list(parsed.researchAndInnovation?.industryPartnerships)
  },
  communityEngagement: {
    socialImpactPrograms: list(parsed.communityEngagement?.socialImpactPrograms),
    communityPartnerships: list(parsed.communityEngagement?.communityPartnerships),
    sustainabilityInitiatives: list(parsed.communityEngagement?.sustainabilityInitiatives)
  },
  graduateProfile: {
    description: text(parsed.graduateProfile?.description),
    competencies: list(parsed.graduateProfile?.competencies),
    professionalSkills: list(parsed.graduateProfile?.professionalSkills),
    ethicalCommitments: list(parsed.graduateProfile?.ethicalCommitments)
  },
  facultyProfile: {
    overview: text(parsed.facultyProfile?.overview),
    qualifications: list(parsed.facultyProfile?.qualifications),
    teachingStrengths: list(parsed.facultyProfile?.teachingStrengths)
  },
  competitiveAdvantages: descriptionItems(parsed.competitiveAdvantages),
  brandIdentity: {
    brandPromise: text(parsed.brandIdentity?.brandPromise),
    brandPersonality: list(parsed.brandIdentity?.brandPersonality),
    uniqueValueProposition: text(parsed.brandIdentity?.uniqueValueProposition)
  },
  institutionalCulture: {
    cultureDescription: text(parsed.institutionalCulture?.cultureDescription),
    diversityAndInclusion: text(parsed.institutionalCulture?.diversityAndInclusion),
    innovationMindset: text(parsed.institutionalCulture?.innovationMindset),
    collaborationApproach: text(parsed.institutionalCulture?.collaborationApproach)
  },
  recognitionsAndAchievements: Array.isArray(parsed.recognitionsAndAchievements) ? parsed.recognitionsAndAchievements.map((item) => ({ year: text(item.year), recognition: text(item.recognition), organization: text(item.organization) })).filter((item) => item.year || item.recognition || item.organization) : [],
  futureOutlook: {
    growthPlans: list(parsed.futureOutlook?.growthPlans),
    strategicPriorities: list(parsed.futureOutlook?.strategicPriorities),
    longTermGoals: list(parsed.futureOutlook?.longTermGoals)
  }
};

return {
  json: {
    ok: true,
    agent: 'edwin-university-profile-agent',
    message: 'university profile generado correctamente',
    universityProfile: profile,
    sourceCount: promptContext.sourceCount || 0,
    sources: promptContext.sources || [],
    rawOutput: raw
  }
};

const initialTargets = $('Prepare Research Targets').all().map((item) => item.json || {});
const fetchedItems = items.map((item) => item.json || {});
const webhookInput = $('Webhook - University Profile Agent').first().json || {};
const webhookBody = webhookInput.body && typeof webhookInput.body === 'object' ? webhookInput.body : webhookInput;
const brand = webhookBody.brand || webhookInput.brand || initialTargets[0]?.brand || {};
const preferredLanguage = initialTargets[0]?.preferredLanguage || 'es';

function normalizeUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw.startsWith('http') ? raw : 'https://' + raw);
    url.hash = '';
    return url.toString();
  } catch (error) {
    return '';
  }
}

function getRawContent(item) {
  return String(item.data || item.body || item.html || item.text || item.response || '').trim();
}

function extractLocUrls(raw) {
  return Array.from(String(raw || '').matchAll(/<loc>\s*([^<]+)\s*<\/loc>/gi))
    .map((match) => normalizeUrl(match[1]))
    .filter(Boolean);
}

function scoreUrl(url) {
  const lower = url.toLowerCase();
  let score = 0;
  const positiveWeights = [
    [/about-us|about|quienes-somos|la-universidad|institution|who-we-are/, 90],
    [/mission|vision|mision|visi[o?]n|purpose|values|valores/, 85],
    [/history|historia|legacy|leadership|governance/, 70],
    [/accredit|approvals|consumer-information|certification|licensing|licensure|acreditaci[o?]n/, 68],
    [/student-services|career-services|student-life|campus-life|bienestar|servicios/, 62],
    [/sustainability|sostenibilidad|community|proyeccion|social-impact|diversity|inclusion/, 58],
    [/research|innovation|investigaci[o?]n|innovaci[o?]n/, 52],
    [/programs|academics|academic|areas|faculties|escuelas|programas/, 38]
  ];
  for (const [pattern, weight] of positiveWeights) if (pattern.test(lower)) score += weight;
  const negativePatterns = [
    /wp-content|uploads|\.jpg|\.jpeg|\.png|\.gif|\.webp|\.svg|\.pdf|\.doc|\.zip/,
    /tag\/|category\/|author\/|feed|cart|checkout|privacy|terms|cookie|login|wp-json/,
    /blog\/page\/|page\/\d+|\?/,
    /event|events|news|noticias|admission|apply|tuition|payment|contact|directory|search/
  ];
  for (const pattern of negativePatterns) if (pattern.test(lower)) score -= 45;
  if (lower.endsWith('/')) score += 3;
  return score;
}

const seen = new Set(initialTargets.map((target) => normalizeUrl(target.url)).filter(Boolean));
const candidates = [];

fetchedItems.forEach((item, index) => {
  const target = initialTargets[index] || {};
  const isSitemap = target.sourceType === 'sitemap' || /sitemap/i.test(target.url || '');
  if (!isSitemap) return;
  const urls = extractLocUrls(getRawContent(item));
  urls.forEach((url) => {
    if (!url || seen.has(url)) return;
    const score = scoreUrl(url);
    if (score < 35) return;
    seen.add(url);
    candidates.push({ url, score, sourceType: 'sitemap-discovered-page', discoveredFrom: target.url || '', brand, preferredLanguage });
  });
});

const selected = candidates.sort((a, b) => b.score - a.score || a.url.localeCompare(b.url)).slice(0, 8);

if (selected.length === 0) {
  const fallback = initialTargets.find((target) => target.url && target.sourceType !== 'sitemap') || initialTargets.find((target) => target.url) || {};
  return [{ json: { url: fallback.url || '', sourceIndex: 1, sourceType: 'fallback-existing-page', score: 0, discoveredFrom: 'no-sitemap-candidates', brand, preferredLanguage } }];
}

return selected.map((candidate, index) => ({ json: { ...candidate, sourceIndex: index + 1 } }));
